"""Constructor-based Hadamard matrix optimization for n=29"""
import numpy as np
import random


def construct_hadamard_matrix(n=29):
    """
    Construct a Hadamard-like matrix of size n using optimization methods.

    Args:
        n: Matrix size (default 29)

    Returns:
        n x n matrix with entries +1 or -1
    """

    def det_bareiss(A):
        """Bareiss algorithm for exact integer determinant calculation."""
        size = len(A)
        if size == 0:
            return 1
        M = [row.copy() for row in A]
        for k in range(size - 1):
            if M[k][k] == 0:
                for i in range(k + 1, size):
                    if M[i][k] != 0:
                        M[k], M[i] = M[i], M[k]
                        break
                else:
                    return 0
            for i in range(k + 1, size):
                for j in range(k + 1, size):
                    num = M[i][j] * M[k][k] - M[i][k] * M[k][j]
                    den = M[k - 1][k - 1] if k > 0 else 1
                    M[i][j] = num // den
        return M[-1][-1]

    def hill_climb_with_annealing(A, max_iters=2000, seed=None, temp0=0.5):
        """Hill climbing with simulated annealing for Hadamard matrix optimization."""
        rng = random.Random(seed)
        size = len(A)
        current_matrix = [row.copy() for row in A]
        det_curr = det_bareiss(current_matrix)
        best_det = det_curr
        best_matrix = [row.copy() for row in current_matrix]

        for t in range(1, max_iters + 1):
            # Random flip
            i = rng.randrange(size)
            j = rng.randrange(size)
            old_val = current_matrix[i][j]
            current_matrix[i][j] = -old_val

            # Calculate new determinant
            d_new = det_bareiss(current_matrix)

            # Accept or reject based on simulated annealing
            accept = False
            if abs(d_new) >= abs(det_curr):
                accept = True
            else:
                # Annealing temperature schedule
                T = temp0 / (1.0 + t * 0.001)
                if T > 0 and rng.random() < np.exp((abs(d_new) - abs(det_curr)) / max(1.0, T * abs(det_curr))):
                    accept = True

            if accept:
                det_curr = d_new
                if abs(det_curr) > abs(best_det):
                    best_det = det_curr
                    best_matrix = [row.copy() for row in current_matrix]
            else:
                current_matrix[i][j] = old_val  # Revert

        return np.array(best_matrix), best_det

    def create_structured_start(size):
        """Create a structured starting matrix for optimization."""
        # For N=29, use quadratic residues mod 29
        if size == 29:
            matrix = []
            quadratic_residues = {1, 4, 5, 6, 7, 9, 13, 16, 20, 22, 23, 24, 25, 28}  # QR mod 29
            for i in range(size):
                row = []
                for j in range(size):
                    diff = (i - j) % size
                    if diff in quadratic_residues:
                        row.append(1)
                    else:
                        row.append(-1)
                matrix.append(row)
            return matrix

        # For other sizes with n % 4 == 1, try quadratic residue approach
        elif size > 2 and size % 4 == 1:
            try:
                quadratic_residues = set()
                for i in range(1, size):
                    quadratic_residues.add((i * i) % size)

                matrix = []
                for i in range(size):
                    row = []
                    for j in range(size):
                        diff = (i - j) % size
                        if diff in quadratic_residues:
                            row.append(1)
                        else:
                            row.append(-1)
                    matrix.append(row)
                return matrix
            except Exception:
                pass

        # Random starting point for other cases
        return np.random.choice([-1, 1], size=(size, size)).tolist()

    def create_sylvester_hadamard(size):
        """Create a Sylvester-based Hadamard matrix and pad to desired size."""
        # Start with H2
        h = np.array([[1, 1], [1, -1]])

        # Build up to largest power of 2 <= size
        while h.shape[0] * 2 <= size:
            h = np.kron(h, h)

        # If we have exactly the right size, return it
        if h.shape[0] == size:
            return h.tolist()

        # Otherwise, we need to pad
        # For n=29, we'll have h=16x16, need to add 13 rows/columns
        # Use a simple padding strategy
        matrix = []
        for i in range(size):
            row = []
            for j in range(size):
                if i < h.shape[0] and j < h.shape[1]:
                    row.append(int(h[i, j]))
                else:
                    # For padded rows/columns, use a pattern
                    val = ((i + j) % 3)
                    if val == 0 or val == 1:
                        row.append(1)
                    else:
                        row.append(-1)
            matrix.append(row)
        return matrix

    # Try both quadratic residue and Sylvester-based starts
    start1 = create_structured_start(n)
    start2 = create_sylvester_hadamard(n)

    # Optimize from both
    optimized1, det1 = hill_climb_with_annealing(
        start1, 
        max_iters=2000,
        seed=42,
        temp0=0.5
    )

    optimized2, det2 = hill_climb_with_annealing(
        start2, 
        max_iters=2000,
        seed=123,
        temp0=0.5
    )

    # Keep the best
    if abs(det2) > abs(det1):
        return optimized2
    else:
        return optimized1


